function groupTrackFeatures(track, ctx) {
  const cacheKey = track?.id || trackSignature(track);
  if (ctx.featureCache.has(cacheKey)) return ctx.featureCache.get(cacheKey);

  const aspects = new Set();
  const aspectEvidence = new Map();
  const row = ctx.poolByTrack.get(track?.id);

  // Spotify genre search is only a retrieval hint. It must not masquerade as
  // reliable track metadata, because Search can return surprisingly loose matches.
  for (const query of row?.queries || []) {
    const genre = extractGenreQueryValue(query);
    if (genre) addAspectAndParents(genre, aspects, ctx, aspectEvidence, 0.20, "spotify-genre-query");
  }

  let exactLastFm = false;
  let recentCount = 0;
  let sourceCount = 0;
  let isPolish = false;

  const titleKey = normalizeForSignature(track?.name || "");
  for (const artist of track?.artists || []) {
    const artistKey = normalizeArtistName(artist?.name || "");
    if (!artistKey) continue;

    const artistRow = ctx.artistPool.get(artistKey);
    if (artistRow) {
      recentCount = Math.max(recentCount, Number(artistRow.recentCount || 0));
      sourceCount = Math.max(sourceCount, (artistRow.sources || []).length);
      for (const tag of artistRow.tags || []) {
        addAspectAndParents(tag, aspects, ctx, aspectEvidence, 0.72, "lastfm-artist-tag");
        if (isPolishLastFmTag(tag)) {
          isPolish = true;
          for (const alias of polishTagGenreAliases(tag)) {
            addAspectAndParents(alias, aspects, ctx, aspectEvidence, 0.68, "lastfm-polish-tag-alias");
          }
        }
      }
    }

    const trackRow = ctx.trackPool.get(`${artistKey}|${titleKey}`);
    if (trackRow) {
      exactLastFm = true;
      sourceCount = Math.max(sourceCount, (trackRow.sources || []).length);
      for (const tag of trackRow.tags || []) {
        addAspectAndParents(tag, aspects, ctx, aspectEvidence, 1.00, "lastfm-track-tag");
        if (isPolishLastFmTag(tag)) {
          isPolish = true;
          for (const alias of polishTagGenreAliases(tag)) {
            addAspectAndParents(alias, aspects, ctx, aspectEvidence, 0.92, "lastfm-polish-track-tag-alias");
          }
        }
      }
    }
  }

  // Broad categories are derived evidence. Keep them useful for common-ground
  // scoring, but weaker than the most reliable underlying tag that produced them.
  const snapshot = [...aspects];
  for (const category of genreCategories(snapshot)) {
    const relatedWeights = snapshot
      .map(aspect => aspectEvidence.get(aspect)?.weight || 0)
      .filter(Boolean);
    const inherited = relatedWeights.length ? Math.max(...relatedWeights) * 0.58 : 0.12;
    addAspectAndParents(category, aspects, ctx, aspectEvidence, inherited, "derived-category");
  }

  const features = {
    aspects,
    aspectEvidence,
    artists: trackArtistKeys(track),
    exactLastFm,
    recentCount,
    sourceCount,
    recognizability: recognizabilityScore(track, ctx.retentionSnapshot),
    feedback: feedbackScore(track, ctx.retentionFeedback),
    discovery: !exactLastFm && recentCount <= 0,
    isPolish
  };
  ctx.featureCache.set(cacheKey, features);
  return features;
}
